describe("password rotation", () => {
  const NEW = "senha-nova-0123456789012345678901234567890123";
  const OLD = "senha-antiga-9876543210987654321098765432109876";
  const REMOVED = "senha-removida-5555555555555555555555555555555555";
  const rotation: SessionConfig = {
    name: "h3-rotate",
    password: [NEW, OLD],
    generateId: () => "rotated",
  };

  // Value of the session cookie in a response, decoded as `seal` returns it
  const cookieValue = (res: Response) => {
    const setCookie = res.headers.getSetCookie().find((c) => c.startsWith("h3-rotate="));
    return decodeURIComponent(setCookie!.slice("h3-rotate=".length).split(";")[0]);
  };

  it("seals only with the first password", async () => {
    t.app.get("/write", async (event) => {
      await updateSession(event, rotation, { user: "alice" });
      return "ok";
    });

    const sealed = cookieValue(await t.fetch("/write"));
    expect(await unseal(sealed, NEW, sealDefaults)).toMatchObject({
      data: { user: "alice" },
    });
    await expect(unseal(sealed, OLD, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("opens a session sealed with the old password", async () => {
    t.app.get("/read", async (event) => {
      const session = await getSession(event, rotation);
      return { id: session.id, data: session.data };
    });
    const sealed = await seal(
      { id: "old-session", createdAt: Date.now(), data: { user: "bob" } },
      OLD,
      sealDefaults,
    );

    const res = await t.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
    expect(await res.json()).toMatchObject({ id: "old-session", data: { user: "bob" } });
  });

  it("treats a session sealed with a removed password as new, without error", async () => {
    t.app.get("/read", async (event) => {
      const session = await getSession(event, rotation);
      return { id: session.id, data: session.data };
    });
    const sealed = await seal(
      { id: "removed-session", createdAt: Date.now(), data: { user: "eve" } },
      REMOVED,
      sealDefaults,
    );

    const res = await t.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
    const body = await res.json();
    expect(body.id).not.toBe("removed-session");
    expect(body.data).toEqual({});
  });

  it("reseals with the current password on read, with idleTimeout", async () => {
    t.app.get("/read", async (event) => {
      await getSession(event, { ...rotation, idleTimeout: 60 });
      return "ok";
    });
    const sealed = await seal(
      { id: "old-session", createdAt: Date.now(), data: { user: "bob" } },
      OLD,
      sealDefaults,
    );

    const res = await t.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
    const resealed = cookieValue(res);
    expect(await unseal(resealed, NEW, sealDefaults)).toMatchObject({ id: "old-session" });
    await expect(unseal(resealed, OLD, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("reseals with the current password on read, without idleTimeout", async () => {
    t.app.get("/read", async (event) => {
      await getSession(event, rotation);
      return "ok";
    });
    const sealed = await seal(
      { id: "old-session", createdAt: Date.now(), data: { user: "bob" } },
      OLD,
      sealDefaults,
    );

    const res = await t.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    const resealed = cookieValue(res);
    expect(await unseal(resealed, NEW, sealDefaults)).toMatchObject({ id: "old-session" });
    await expect(unseal(resealed, OLD, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("does not reseal when the current password already opens the session", async () => {
    t.app.get("/read", async (event) => {
      await getSession(event, rotation);
      return "ok";
    });
    const sealed = await seal(
      { id: "new-session", createdAt: Date.now(), data: { user: "carol" } },
      NEW,
      sealDefaults,
    );

    const res = await t.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("applies the legacy 1-iteration fallback to each password", async () => {
    t.app.get("/read", async (event) => {
      const session = await getSession(event, rotation);
      return { id: session.id, data: session.data };
    });
    const legacySealed = await seal(
      { id: "legacy-session", createdAt: Date.now(), data: { user: "dave" } },
      OLD,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    const res = await t.fetch("/read", { headers: { Cookie: `h3-rotate=${legacySealed}` } });
    expect(await res.json()).toMatchObject({
      id: "legacy-session",
      data: { user: "dave" },
    });
    const resealed = cookieValue(res);
    expect(await unseal(resealed, NEW, sealDefaults)).toMatchObject({
      id: "legacy-session",
    });
  });

  it("rejects an empty password list", async () => {
    t.app.get("/empty", async (event) => {
      try {
        await getSession(event, { name: "h3-rotate", password: [] });
        return "no error";
      } catch (error) {
        return (error as Error).message;
      }
    });

    const res = await t.fetch("/empty");
    expect(await res.text()).toMatch(/at least one/i);
  });

  it("rejects a password in the list that is too short", async () => {
    t.app.get("/short", async (event) => {
      try {
        await getSession(event, { name: "h3-rotate", password: [NEW, "curta"] });
        return "no error";
      } catch (error) {
        return (error as Error).message;
      }
    });

    const res = await t.fetch("/short");
    expect(await res.text()).toMatch(/too short/i);
  });

  it("stops at a non-HMAC error instead of trying the next password", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const sealed = await seal({ id: "expired", createdAt: t0, data: {} }, OLD, {
        ...sealDefaults,
        ttl: 1000,
      });
      vi.setSystemTime(t0 + 10_000);
      t.app.get("/expired", async (event) => {
        try {
          await unsealSession(event, { ...rotation, maxAge: 3600 }, sealed);
          return "opened";
        } catch (error) {
          return (error as Error).message;
        }
      });

      const res = await t.fetch("/expired");
      expect(await res.text()).toBe("Expired seal");
    } finally {
      vi.useRealTimers();
    }
  });
});

